 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Grid separators contain almost none of the ordinary interior color.
    row_lines = [r for r in range(h) if sum(v == background for v in grid[r]) <= 1]
    col_lines = [c for c in range(w) if sum(grid[r][c] == background for r in range(h)) <= 1]

    out = []
    for i in range(len(row_lines) - 1):
        row = []
        for j in range(len(col_lines) - 1):
            corners = [grid[row_lines[i]][col_lines[j]], grid[row_lines[i]][col_lines[j + 1]],
                       grid[row_lines[i + 1]][col_lines[j]], grid[row_lines[i + 1]][col_lines[j + 1]]]
            marker = corners[0]
            if marker != background and len(set(corners)) == 1:
                row.append(marker)
            else:
                row.append(background)
        out.append(row)
    return out
